-- Progress counter for the generation run. Counts only — safe for anon,
-- which is what lets the coordinating session watch the run complete.
CREATE OR REPLACE FUNCTION public.national_question_progress()
RETURNS TABLE(category_slug text, lang text, total bigint, live bigint)
LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  SELECT c.category_id, c.language, count(q.id),
         count(q.id) FILTER (WHERE q.in_production)
  FROM categories c
  LEFT JOIN questions q ON q.category_id = c.id AND q.is_active
  WHERE c.is_language_specific AND c.language <> 'ka'
  GROUP BY c.category_id, c.language ORDER BY c.category_id;
$$;
REVOKE ALL ON FUNCTION public.national_question_progress() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.national_question_progress() TO anon, authenticated, service_role;

COMMIT;
